static SatchelGuestTransfers *actual_transfers;
SatchelGuestTransfers *present_test_create_checked(SatchelGuestPools*p,SatchelGuestPoolDeviceValidator v,SatchelGuestPoolCheckedRangeGuard g,void*c){actual_transfers=satchel_guest_transfers_create_checked(p,v,g,c);return actual_transfers;}
static void wait_present(uint64_t lease,int cancel){SatchelGuestPresentQueueProgress p={0};for(unsigned i=0;i<10000;i++){uint32_t s=satchel_guest_transfers_present_poll(actual_transfers,lease,1,cancel,&p);check(s==SATCHEL_GUEST_POOL_OK||s==SATCHEL_GUEST_POOL_BUSY||s==SATCHEL_GUEST_TRANSFER_CANCELLED);if(p.drained){check(p.ready==(uint32_t)!cancel&&p.cancelled==(uint32_t)cancel);return;}}check(0);}
int main(void){int original=original_compute_main();unsigned baseline=checks;check(original==0);Fixture f;program_prepare(&f);uint64_t h=compute_record(&f,0x1000);ok(&f,"nvnQueueSubmitCommands",QUEUE,1,HANDLES,0,0);check(actual_transfers!=NULL);uint64_t lease=0;SatchelGuestPresentQueueInfo info;check(!satchel_guest_transfers_present_prepare(actual_transfers,f.cpu,QUEUE,DEVICE,&lease,&info)&&lease&&info.sequence==1);call(&f,"nvnQueueSubmitCommands",QUEUE,1,HANDLES,0,0,SATCHEL_GUEST_DISPATCH_RESOURCE_BUSY);call(&f,"nvnQueueFinalize",QUEUE,0,0,0,0,SATCHEL_GUEST_DISPATCH_RESOURCE_BUSY);check(satchel_guest_transfers_present_release(actual_transfers,lease)==SATCHEL_GUEST_POOL_BUSY);wait_present(lease,0);check(!satchel_vulkan_submission_live_count());check(!satchel_guest_transfers_present_release(actual_transfers,lease));ok(&f,"nvnQueueFinish",QUEUE,0,0,0,0);output_check(&f,12,12);ok(&f,"nvnDeviceFinalizeCommandHandle",DEVICE,h,0,0,0);drop(&f);
 program_prepare(&f);compute_record(&f,0x1000);ok(&f,"nvnQueueSubmitCommands",QUEUE,1,HANDLES,0,0);check(!satchel_guest_transfers_present_prepare(actual_transfers,f.cpu,QUEUE,DEVICE,&lease,&info));check(satchel_cpu_probe_try_destroy(f.cpu));f.cpu=NULL;check(satchel_guest_dispatch_handoff(&f.dispatch)&&!f.dispatch);SatchelGuestRetirementReport report;check(satchel_guest_dispatch_retirement_poll(NULL,NULL,&report)==SATCHEL_GUEST_RETIRE_PENDING);wait_present(lease,1);check(!satchel_guest_transfers_present_release(actual_transfers,lease));collect();
 printf("Presentation compute lease: %u added assertions; prior interpreted compute regression %u retained.\n",checks-baseline,baseline);return 0;}
